1	// Test-only fixture for the API test files: one server per describe block.
2	import assert from 'node:assert/strict';
3	import path from 'node:path';
4	import { startServer, makeTempDir, removeDir, request, postJson, JSON_CT } from './helpers.mjs';
5	
6	export const NOT_FOUND = { error: 'not found' };
7	export const NOT_ALLOWED = { error: 'method not allowed' };
8	export const BAD_DATE = { error: 'date must be a valid YYYY-MM-DD date' };
9	
10	export function fixture() {
11	  const state = { dir: null, server: null };
12	  const api = {
13	    get port() { return state.server.port; },
14	    get dataFile() { return path.join(state.dir, 'data.json'); },
15	    async start() {
16	      state.dir = await makeTempDir();
17	      state.server = await startServer({ env: { DATA_FILE: api.dataFile } });
18	    },
19	    async restart() {
20	      await state.server.stop();
21	      state.server = await startServer({ env: { DATA_FILE: api.dataFile } });
22	    },
23	    async stop() {
24	      try {
25	        if (state.server) await state.server.stop();
26	      } finally {
27	        if (state.dir) await removeDir(state.dir);
28	      }
29	    },
30	  };
31	  return api;
32	}
33	
34	export function assertJson(res, status, expected) {
35	  assert.equal(res.status, status);
36	  assert.equal(res.headers['content-type'], JSON_CT);
37	  assert.deepEqual(res.json, expected);
38	}
39	
40	export async function create(port, overrides) {
41	  const res = await postJson(port, {
42	    room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides,
43	  });
44	  assert.equal(res.status, 201, res.text);
45	  return res.json;
46	}
47	
48	export async function listBookings(port, query = '') {
49	  const res = await request(port, { path: `/api/bookings${query}` });
50	  assertJson(res, 200, res.json);
51	  return res.json.bookings;
52	}
