1	// Minimal fake DOM + controllable fake fetch for running public/app.js in node:vm.
2	// Only the members the spec allows the script to use exist; anything else throws.
3	import vm from 'node:vm';
4	import fs from 'node:fs';
5	
6	const APP_PATH = new URL('../public/app.js', import.meta.url);
7	
8	export class FakeText {
9	  constructor(data) {
10	    this.nodeType = 3;
11	    this.data = data;
12	  }
13	}
14	
15	function toNodes(items) {
16	  return items.map((item) => (typeof item === 'string' ? new FakeText(item) : item));
17	}
18	
19	function textOf(node) {
20	  return node.nodeType === 3 ? node.data : node.childNodes.map(textOf).join('');
21	}
22	
23	export class FakeElement {
24	  #value = undefined;
25	
26	  constructor(tag, props = {}) {
27	    this.tagName = tag.toUpperCase();
28	    this.id = props.id ?? '';
29	    this.childNodes = [];
30	    this.listeners = new Map();
31	    this.type = props.type ?? '';
32	    this.disabled = false;
33	  }
34	
35	  get value() {
36	    if (this.#value !== undefined) return this.#value;
37	    if (this.tagName === 'SELECT') {
38	      const first = this.childNodes[0];
39	      return first ? first.value : '';
40	    }
41	    return '';
42	  }
43	
44	  set value(v) {
45	    this.#value = String(v);
46	  }
47	
48	  get textContent() {
49	    return this.childNodes.map(textOf).join('');
50	  }
51	
52	  set textContent(text) {
53	    const s = String(text);
54	    this.childNodes = s === '' ? [] : [new FakeText(s)];
55	  }
56	
57	  append(...items) {
58	    this.childNodes = [...this.childNodes, ...toNodes(items)];
59	  }
60	
61	  replaceChildren(...items) {
62	    this.childNodes = toNodes(items);
63	  }
64	
65	  addEventListener(type, fn) {
66	    this.listeners.set(type, [...(this.listeners.get(type) ?? []), fn]);
67	  }
68	
69	  // Test-only: fire an event and return it.
70	  dispatch(type) {
71	    const event = {
72	      type,
73	      target: this,
74	      defaultPrevented: false,
75	      preventDefault() { this.defaultPrevented = true; },
76	    };
77	    for (const fn of this.listeners.get(type) ?? []) fn(event);
78	    return event;
79	  }
80	}
81	
82	function makeFetch(calls, elements) {
83	  return function fetch(url, options) {
84	    return new Promise((resolve, reject) => {
85	      calls.push({
86	        url,
87	        options,
88	        bookDisabledAtCall: elements.book.disabled,
89	        respond(status, body) {
90	          const hasBody = status !== 204;
91	          resolve({
92	            status,
93	            json() {
94	              if (!hasBody) return Promise.reject(new SyntaxError('no body'));
95	              if (typeof body === 'string') {
96	                try { return Promise.resolve(JSON.parse(body)); } catch (e) { return Promise.reject(e); }
97	              }
98	              return Promise.resolve(JSON.parse(JSON.stringify(body)));
99	            },
100	          });
101	        },
102	        fail() { reject(new TypeError('fetch failed')); },
103	      });
104	    });
105	  };
106	}
107	
108	function makeElements() {
109	  return {
110	    form: new FakeElement('form', { id: 'booking-form' }),
111	    room: new FakeElement('select', { id: 'room' }),
112	    title: new FakeElement('input', { id: 'title', type: 'text' }),
113	    date: new FakeElement('input', { id: 'date', type: 'date' }),
114	    start: new FakeElement('input', { id: 'start', type: 'time' }),
115	    end: new FakeElement('input', { id: 'end', type: 'time' }),
116	    book: new FakeElement('button', { id: 'book', type: 'submit' }),
117	    filter: new FakeElement('input', { id: 'filter-date', type: 'date' }),
118	    showAll: new FakeElement('button', { id: 'show-all', type: 'button' }),
119	    list: new FakeElement('ul', { id: 'booking-list' }),
120	    error: new FakeElement('p', { id: 'error' }),
121	  };
122	}
123	
124	const tick = () => new Promise((r) => setImmediate(r));
125	
126	export async function flush() {
127	  for (let i = 0; i < 6; i += 1) await tick();
128	}
129	
130	// Runs the app. Returns { ...elements, fetchCalls, flush, listTexts }.
131	export function loadApp() {
132	  const elements = makeElements();
133	  const byId = new Map(Object.values(elements).map((el) => [el.id, el]));
134	  const fetchCalls = [];
135	  const document = {
136	    getElementById: (id) => byId.get(id) ?? null,
137	    createElement: (tag) => new FakeElement(tag),
138	  };
139	  const ctx = vm.createContext({ document, fetch: makeFetch(fetchCalls, elements) });
140	  new vm.Script(fs.readFileSync(APP_PATH, 'utf8'), { filename: 'app.js' }).runInContext(ctx);
141	  const listTexts = () => elements.list.childNodes.map((li) => {
142	    const [first, second] = li.childNodes;
143	    return [li.childNodes.length, first?.nodeType, first?.data,
144	      second?.tagName, second?.type, second?.textContent];
145	  });
146	  return { ...elements, fetchCalls, flush, listTexts };
147	}
148	
149	// Convert a cross-realm value into a host-realm plain value for deepStrictEqual.
150	export const plain = (value) => JSON.parse(JSON.stringify(value));
151	
152	export const booking = (id, over = {}) => ({
153	  id, room: 'Aurora', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00', ...over,
154	});
155	
156	// Load the app, answer the rooms and list fetches, and settle.
157	export async function loadReady(bookings = [], rooms = ['Aurora', 'Borealis', 'Cosmos']) {
158	  const app = loadApp();
159	  app.fetchCalls[0].respond(200, { rooms });
160	  app.fetchCalls[1].respond(200, { bookings });
161	  await app.flush();
162	  return app;
163	}
