1	// Startup behaviour: PORT checks, data file reading, ordering, stdout.
2	import { describe, test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import fs from 'node:fs';
5	import net from 'node:net';
6	import path from 'node:path';
7	import {
8	  startServer, runUntilExit, request, postJson, booking, makeTempDir, removeDir, LISTEN_RE,
9	} from './helpers.mjs';
10	
11	async function withTmp(fn) {
12	  const dir = await makeTempDir();
13	  try {
14	    return await fn(dir);
15	  } finally {
16	    await removeDir(dir);
17	  }
18	}
19	
20	async function withServer(options, fn) {
21	  const server = await startServer(options);
22	  try {
23	    return await fn(server);
24	  } finally {
25	    await server.stop();
26	  }
27	}
28	
29	function listenBusy() {
30	  return new Promise((resolve, reject) => {
31	    const srv = net.createServer();
32	    srv.once('error', reject);
33	    srv.listen(0, '127.0.0.1', () => resolve(srv));
34	  });
35	}
36	
37	function closeNet(srv) {
38	  return new Promise((resolve) => srv.close(() => resolve()));
39	}
40	
41	function isPortInUse(port) {
42	  return new Promise((resolve) => {
43	    const sock = net.connect(port, '127.0.0.1');
44	    sock.once('connect', () => { sock.destroy(); resolve(true); });
45	    sock.once('error', () => resolve(false));
46	  });
47	}
48	
49	function assertOneLineFailure(res) {
50	  assert.equal(res.code, 1);
51	  assert.equal(res.stdout, '');
52	  assert.match(res.stderr, /^[^\n]+\n$/);
53	  assert.doesNotMatch(res.stderr, /^\s+at /m);
54	  assert.doesNotMatch(res.stderr, /Error/);
55	}
56	
57	describe('A. PORT validation', () => {
58	  const bad = ['+80', ' 80', '80 ', '65536', '1e3', '0x50', '-1', 'abc', '８０', '99999999999999999999'];
59	  for (const port of bad) {
60	    test(`PORT ${JSON.stringify(port)} exits 1 with one stderr line`, () => withTmp(async (dir) => {
61	      const res = await runUntilExit({ env: { PORT: port, DATA_FILE: path.join(dir, 'b.json') } });
62	      assertOneLineFailure(res);
63	    }));
64	  }
65	
66	  for (const port of ['00000', '65535']) {
67	    test(`PORT ${port} starts`, () => withTmp(async (dir) => {
68	      await withServer({ env: { PORT: port, DATA_FILE: path.join(dir, 'b.json') } }, async (s) => {
69	        if (port === '65535') assert.equal(s.port, 65535);
70	        else assert.ok(s.port > 0);
71	      });
72	    }));
73	  }
74	
75	  test('empty PORT means 3000', async (t) => {
76	    await withTmp(async (dir) => {
77	      let server;
78	      try {
79	        server = await startServer({ env: { PORT: '', DATA_FILE: path.join(dir, 'b.json') } });
80	      } catch (err) {
81	        if (await isPortInUse(3000)) { t.skip('port 3000 is in use'); return; }
82	        throw err;
83	      }
84	      try {
85	        assert.equal(server.port, 3000);
86	        assert.equal(server.out.stdout, 'listening on http://127.0.0.1:3000\n');
87	      } finally {
88	        await server.stop();
89	      }
90	    });
91	  });
92	
93	  test('port in use exits 1 with one stderr line', () => withTmp(async (dir) => {
94	    const busy = await listenBusy();
95	    try {
96	      const port = String(busy.address().port);
97	      const res = await runUntilExit({ env: { PORT: port, DATA_FILE: path.join(dir, 'b.json') } });
98	      assertOneLineFailure(res);
99	    } finally {
100	      await closeNet(busy);
101	    }
102	  }));
103	});
104	
105	describe('B. startup order', () => {
106	  test('invalid PORT is checked before the data file', () => withTmp(async (dir) => {
107	    const res = await runUntilExit({ env: { PORT: 'abc', DATA_FILE: dir } });
108	    assert.equal(res.code, 1);
109	    assert.equal(res.stdout, '');
110	    assert.notEqual(res.stderr, `cannot read data file ${dir}\n`);
111	    assert.doesNotMatch(res.stderr, /cannot read data file/);
112	  }));
113	
114	  test('data file is read before listening', () => withTmp(async (dir) => {
115	    const busy = await listenBusy();
116	    try {
117	      const file = path.join(dir, 'bad.json');
118	      fs.writeFileSync(file, 'not json');
119	      const res = await runUntilExit({ env: { PORT: String(busy.address().port), DATA_FILE: file } });
120	      assert.equal(res.code, 1);
121	      assert.equal(res.stdout, '');
122	      assert.equal(res.stderr, `cannot read data file ${file}\n`);
123	    } finally {
124	      await closeNet(busy);
125	    }
126	  }));
127	});
128	
129	describe('C. unreadable data file', () => {
130	  async function expectBad(dir, name, env = {}, cwd) {
131	    const res = await runUntilExit({ env: { PORT: '0', DATA_FILE: name, ...env }, cwd });
132	    assert.equal(res.code, 1);
133	    assert.equal(res.stdout, '');
134	    assert.equal(res.stderr, `cannot read data file ${name}\n`);
135	  }
136	
137	  const contents = {
138	    'empty file': '',
139	    'not json': 'not json',
140	    'JSON array': '[]',
141	    'JSON null': 'null',
142	    'empty object': '{}',
143	  };
144	  for (const [label, content] of Object.entries(contents)) {
145	    test(label, () => withTmp(async (dir) => {
146	      const file = path.join(dir, 'b.json');
147	      fs.writeFileSync(file, content);
148	      await expectBad(dir, file);
149	    }));
150	  }
151	
152	  test('path is a directory', () => withTmp(async (dir) => {
153	    await expectBad(dir, dir);
154	  }));
155	
156	  test('valid store with a UTF-8 BOM', () => withTmp(async (dir) => {
157	    const file = path.join(dir, 'b.json');
158	    fs.writeFileSync(file, Buffer.concat([
159	      Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from('{"nextId":1,"bookings":[]}'),
160	    ]));
161	    await expectBad(dir, file);
162	  }));
163	
164	  test('relative DATA_FILE is shown as given', () => withTmp(async (dir) => {
165	    fs.mkdirSync(path.join(dir, 'sub'));
166	    fs.writeFileSync(path.join(dir, 'bad.json'), 'nope');
167	    await expectBad(dir, 'sub/../bad.json', {}, dir);
168	  }));
169	
170	  test('parent is a regular file', () => withTmp(async (dir) => {
171	    const file = path.join(dir, 'plain');
172	    fs.writeFileSync(file, 'x');
173	    await expectBad(dir, `${file}/x.json`);
174	  }));
175	
176	  for (const [label, env] of [['unset', {}], ['empty', { DATA_FILE: '' }]]) {
177	    test(`DATA_FILE ${label}: bookings.json directory in cwd`, () => withTmp(async (dir) => {
178	      fs.mkdirSync(path.join(dir, 'bookings.json'));
179	      const res = await runUntilExit({ env: { PORT: '0', ...env }, cwd: dir });
180	      assert.equal(res.code, 1);
181	      assert.equal(res.stdout, '');
182	      assert.equal(res.stderr, 'cannot read data file bookings.json\n');
183	    }));
184	  }
185	});
186	
187	describe('D. ENOENT means no bookings', () => {
188	  async function checkMissing(file, probe) {
189	    await withServer({ env: { DATA_FILE: file } }, async (s) => {
190	      const res = await request(s.port, { path: '/api/bookings' });
191	      assert.equal(res.status, 200);
192	      assert.deepEqual(res.json, { bookings: [] });
193	      await request(s.port, { path: '/api/rooms' });
194	      assert.equal(fs.existsSync(probe), false);
195	    });
196	    assert.equal(fs.existsSync(probe), false);
197	  }
198	
199	  test('missing file', () => withTmp(async (dir) => {
200	    const file = path.join(dir, 'b.json');
201	    await checkMissing(file, file);
202	  }));
203	
204	  test('missing folder', () => withTmp(async (dir) => {
205	    const file = path.join(dir, 'nope', 'deeper', 'b.json');
206	    await checkMissing(file, path.join(dir, 'nope'));
207	  }));
208	});
209	
210	describe('E. stdout', () => {
211	  test('only the listening line is ever written', () => withTmp(async (dir) => {
212	    const file = path.join(dir, 'b.json');
213	    let port;
214	    let out;
215	    await withServer({ env: { DATA_FILE: file } }, async (s) => {
216	      port = s.port;
217	      out = s.out;
218	      assert.equal((await request(port, { path: '/api/bookings' })).status, 200);
219	      const created = await postJson(port, booking());
220	      assert.equal(created.status, 201);
221	      assert.equal((await postJson(port, booking({ room: 'x' }))).status, 400);
222	      const del = await request(port, { method: 'DELETE', path: `/api/bookings/${created.json.id}` });
223	      assert.equal(del.status, 204);
224	      assert.equal((await request(port, { path: '/nothing' })).status, 404);
