9	const HTML_PATH = path.join(ROOT, 'public', 'index.html');
10	const JS_PATH = path.join(ROOT, 'public', 'app.js');
11	const HTML_CT = 'text/html; charset=utf-8';
12	const JS_CT = 'text/javascript; charset=utf-8';
13	const VOID = new Set(['meta', 'input', 'br', 'link', 'img', 'hr']);
14	const RAW = new Set(['script', 'style']);
15	const ROOMS = ['Aurora', 'Borealis', 'Cosmos'];
16	
17	// ---- tiny tokenizer ----
18	const ATTR_RE = /([^\s"'<>\/=]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g;
19	
20	function parseAttrs(src) {
21	  const attrs = {};
22	  for (const m of src.matchAll(ATTR_RE)) {
23	    attrs[m[1].toLowerCase()] = m[2] ?? m[3] ?? m[4] ?? '';
24	  }
25	  return attrs;
26	}
27	
28	function tokenize(html) {
29	  const tokens = [];
30	  const re = /<!--[\s\S]*?-->|<![^>]*>|<\/([a-zA-Z][^\s>]*)\s*>|<([a-zA-Z][^\s\/>]*)((?:"[^"]*"|'[^']*'|[^'">])*)>|([^<]+|<)/g;
31	  let m;
32	  while ((m = re.exec(html)) !== null) {
33	    if (m[1]) tokens.push({ t: 'end', name: m[1].toLowerCase() });
34	    else if (m[2]) {
35	      const name = m[2].toLowerCase();
36	      tokens.push({ t: 'start', name, attrs: parseAttrs(m[3]) });
37	      if (RAW.has(name)) {
38	        const close = html.toLowerCase().indexOf(`</${name}`, re.lastIndex);
39	        if (close > re.lastIndex) tokens.push({ t: 'text', text: html.slice(re.lastIndex, close) });
40	        re.lastIndex = close < 0 ? html.length : close;
41	      }
42	    } else if (m[4] !== undefined) tokens.push({ t: 'text', text: m[4] });
43	  }
44	  return tokens;
45	}
46	
47	// Index of the end token matching the start token at i (i itself for void tags).
48	function endIndex(tokens, i) {
49	  const name = tokens[i].name;
50	  if (VOID.has(name)) return i;
51	  let depth = 0;
52	  for (let j = i; j < tokens.length; j++) {
53	    const tk = tokens[j];
54	    if (tk.name !== name) continue;
55	    if (tk.t === 'start') depth++;
56	    else if (tk.t === 'end' && --depth === 0) return j;
57	  }
58	  return -1;
59	}
60	
61	function textBetween(tokens, i) {
62	  const e = endIndex(tokens, i);
63	  assert.ok(e > i, `no end tag for <${tokens[i].name}>`);
64	  const inner = tokens.slice(i + 1, e);
65	  assert.ok(inner.every((x) => x.t === 'text'), `<${tokens[i].name}> holds nested tags`);
66	  return inner.map((x) => x.text).join('');
67	}
68	
69	function starts(tokens, name, attrs = {}) {
70	  const out = [];
71	  tokens.forEach((tk, i) => {
72	    if (tk.t !== 'start' || tk.name !== name) return;
73	    if (Object.entries(attrs).every(([k, v]) => tk.attrs[k] === v)) out.push(i);
74	  });
75	  return out;
76	}
77	
78	function only(tokens, name, attrs) {
79	  const found = starts(tokens, name, attrs);
80	  assert.equal(found.length, 1, `expected exactly one <${name}> ${JSON.stringify(attrs)}`);
81	  return found[0];
82	}
